// DENORMALIZED: Customer info duplicated in every order
record OrderDenormalized(
    Long orderId,
    String customerName,
    String customerEmail,    // duplicated across all orders
    String customerAddress,  // duplicated across all orders
    String productName,
    BigDecimal price
) {}

// NORMALIZED: Customer stored once, referenced by foreign key
record Customer(
    Long customerId,
    String name,
    String email,
    String address
) {}

record Order(
    Long orderId,
    Long customerId,         // foreign key to Customer
    String productName,
    BigDecimal price
) {}

// VIOLATES 1NF: phoneNumbers stores multiple values
record EmployeeBad(
    Long employeeId,
    String name,
    String phoneNumbers  // "555-1234, 555-5678, 555-9999" - NOT atomic!
) {}

// CORRECT 1NF: each phone number is a separate row
record Employee(
    Long employeeId,
    String name
) {}

record EmployeePhone(
    Long phoneId,
    Long employeeId,     // foreign key to Employee
    String phoneNumber,  // atomic: single value
    String phoneType     // "mobile", "home", "work"
) {}

// Now you can query: SELECT * FROM employee_phone WHERE phone_number LIKE '555-1234'
// And count: SELECT employee_id, COUNT(*) FROM employee_phone GROUP BY employee_id

// VIOLATES 2NF: composite key (studentId, courseId)
// but studentName depends only on studentId (partial dependency)
record EnrollmentBad(
    Long studentId,      // part 1 of composite key
    Long courseId,       // part 2 of composite key
    String studentName,  // depends only on studentId - PARTIAL!
    String courseName,   // depends only on courseId - PARTIAL!
    LocalDate enrollDate
) {}

// CORRECT 2NF: split into three tables
record Student(
    Long studentId,
    String studentName
) {}

record Course(
    Long courseId,
    String courseName
) {}

record Enrollment(
    Long studentId,
    Long courseId,
    LocalDate enrollDate  // depends on full composite key
) {}

// VIOLATES 3NF: city depends on zipCode (non-key), not studentId (key)
record StudentBad(
    Long studentId,      // primary key
    String name,
    String zipCode,
    String city          // transitively dependent: studentId -> zipCode -> city
) {}

// CORRECT 3NF: split into two tables
record Student(
    Long studentId,
    String name,
    String zipCode       // foreign key to ZipCode
) {}

record ZipCode(
    String zipCode,      // primary key
    String city,
    String state
) {}

// Now city is stored once per zip code, not once per student
// Query: SELECT s.name, z.city FROM student s JOIN zip_code z ON s.zip_code = z.zip_code

// INITIAL: denormalized table (violates 1NF, 2NF, 3NF)
record OrderDenormalized(
    Long orderId,
    String customerName,
    String customerZip,
    String customerCity,      // transitive: depends on zip
    String productNames       // "Laptop, Mouse, Keyboard" - not atomic!
) {}

// STEP 1 (1NF): fix non-atomic productNames
record Order1NF(
    Long orderId,
    Long productId,           // composite key part 1
    String customerName,
    String customerZip,
    String customerCity,      // still transitive
    String productName
) {}

// STEP 2 (2NF): remove partial dependencies on orderId
record Order(
    Long orderId,
    String customerName,
    String customerZip,
    String customerCity       // still transitive
) {}

record OrderItem(
    Long orderId,
    Long productId,
    String productName
) {}

// STEP 3 (3NF): remove transitive dependency (city depends on zip)
record OrderFinal(
    Long orderId,
    String customerName,
    String customerZip
) {}

record ZipCity(
    String zipCode,
    String city
) {}

// DENORMALIZED: One table for library copies with redundant book data
record LibraryCopyBad(
    Long copyId,
    String isbn,           // duplicated for every copy
    String bookTitle,      // duplicated for every copy
    String author,         // duplicated for every copy
    String location,
    LocalDate acquiredDate
) {}

// UPDATE ANOMALY: Change book title requires updating all copy rows
// INSERT ANOMALY: Can't add book metadata without a physical copy
// DELETE ANOMALY: Deleting last copy loses all book metadata

// NORMALIZED: Separate book metadata from physical copies
record Book(
    String isbn,           // primary key
    String title,
    String author,
    String publisher
) {}

record LibraryCopy(
    Long copyId,
    String isbn,           // foreign key to Book
    String location,
    LocalDate acquiredDate
) {}

// Now: Update title once. Add books without copies. Delete copies without losing books.
